import { AppExtensionProtocolDefinition } from '@castify/app-extension-messaging';
import { setExtensionIcon } from '@castify/record-mv3/chrome-actions';
import { environment } from '@castify/record-mv3/environment';
import { getFirebaseAccessToken } from '@castify/record-mv3/observability';
import { ServiceWorkerLogger } from '@cfy/fe-monitoring';
import {
  addObservabilityMessage,
  cleanUpObservabilityData,
  createObservabilityStorage,
  generateIngestionRollup,
  getObservabilityMessagesByHandoffId,
  getStudioTabs,
  maybeSaveStudioTabInfo,
} from './ingestion-summary';
import { createServiceWorkerProtocolHandler } from './service-worker-protocol-handler';
import { isSensitiveRecordingState } from '../controller/util/isSensitiveRecordingState';
import { migrateMv2Settings } from './migrations/migrate-mv2-settings';
import { SCHEMA } from './util/schema';
import {
  getMigrationsInRequiredOrder,
  runMigrations,
} from './migrations/migration-tools';
import { mv3Migrations } from './migrations/mv3-migrations';
import { authScript } from './auth-script';
import { signOutOfExtension } from '@castify/record-mv3/common/auth';
import { useAuthStore } from '@castify/record-mv3/common/stores';
import { throttle } from 'lodash';
import { IRecordingStoreRecord } from '@castify/record-mv3/record-components';
import { getExtensionBrowserType } from '@castify/record-mv3/environment';
import { counterScript } from './counter-script';
import { focusControllerTab } from '@castify/record-mv3/common';

const currentVersion =
  chrome.runtime.getManifest().version_name + getExtensionBrowserType();

const logger = new ServiceWorkerLogger(
  environment.logServiceUrl,
  getFirebaseAccessToken,
  {
    appName: 'record-mv3-background-worker',
    buildId: currentVersion,
  },
);

interface ControllerIdStorageResult {
  controllerTabId: number;
  applicationTabId: number;
}

interface RecorderStatusStorageResult {
  recorderStatus: string;
}

useAuthStore.getState().loadStore();

export function initBackgroundContentScript() {
  const openGettingStartedPage = async () =>
    await chrome.tabs.create({
      url: `${environment.extensionOrigin}/getting-started.html`,
    });

  const OFFSCREEN_DOCUMENT_PATH = chrome.runtime.getURL('offscreen.html');

  chrome.runtime.onMessage.addListener((message) => {
    if (message.type === 'log') {
      logger.info('Message from extension', message);
    }
  });

  chrome.runtime.onMessage.addListener((message, _, sendResponse) => {
    if (
      message.target === 'background' &&
      message.type === 'ENSURE_OFFSCREEN_DOCUMENT'
    ) {
      createOffscreenDocument()
        .then(() => {
          sendResponse({ success: true });
        })
        .catch((error) => {
          sendResponse({ success: false, errorMessage: error.message });
        });
      return true;
    }
    return false;
  });

  /**
   * Callable function to create the offscreen document.
   */
  async function createOffscreenDocument() {
    try {
      if (!(await hasDocument())) {
        await chrome.offscreen.createDocument({
          url: OFFSCREEN_DOCUMENT_PATH,
          reasons: ['DISPLAY_MEDIA' as chrome.offscreen.Reason],
          justification: 'To interact with user media',
        });
      }
      // No need to send PiP start/stop message here, just ensure the document is ready
    } catch (error) {
      logger.warn('Error in ensuring offscreen document:', error);
    }
  }
  /**
   * Checks if there is an offscreen document.
   */
  async function hasDocument() {
    // Check all windows controlled by the service worker if one of them is the offscreen document
    // clients availble in mv3 sw https://developer.mozilla.org/en-US/docs/Web/API/Clients
    const matchedClients = await clients.matchAll();
    for (const client of matchedClients) {
      if (client.url.endsWith(OFFSCREEN_DOCUMENT_PATH)) {
        return true;
      }
    }
    return false;
  }

  // Log Command messages
  chrome.runtime.onMessage.addListener((message, sender, sendResponse) => {
    if (message.type === 'refreshFirebaseToken') return false;
    if (message.command === 'firestore-options') return true;

    sendResponse({ status: 'Message received' });
    return true;
  });

  async function removeInvalidVideos() {
    try {
      // Get the recordingStore from local storage
      const { recordingStore } = await chrome.storage.local.get(
        'recordingStore',
      );
      if (!recordingStore || !recordingStore.recordingList) {
        return;
      }

      // Create sets to track duplicates
      const idSet = new Set<string>();
      const driveFileIdSet = new Set<string>();
      const videoRegistryIdSet = new Set<string>();

      // Filter out duplicates
      const uniqueRecordingList = recordingStore.recordingList.filter(
        (record: IRecordingStoreRecord) => {
          let isDuplicate = false;

          if (idSet.has(record.id)) {
            isDuplicate = true;
          } else {
            idSet.add(record.id);
          }

          if (record.metadata) {
            if (record.metadata.driveFileId) {
              if (driveFileIdSet.has(record.metadata.driveFileId)) {
                isDuplicate = true;
              } else {
                driveFileIdSet.add(record.metadata.driveFileId);
              }
            }

            if (record.metadata.videoRegistryId) {
              if (videoRegistryIdSet.has(record.metadata.videoRegistryId)) {
                isDuplicate = true;
              } else {
                videoRegistryIdSet.add(record.metadata.videoRegistryId);
              }
            }
          }

          return !isDuplicate;
        },
      );

      // Filter out records with 0 duration
      const finalRecordingList = uniqueRecordingList.filter(
        (record: IRecordingStoreRecord) => {
          return record.metadata.duration && record.metadata.duration > 0;
        },
      );

      // Update the recordingStore in local storage
      recordingStore.recordingList = finalRecordingList;
      await chrome.storage.local.set({ recordingStore });
    } catch (error) {
      logger.error('Error while cleaning recordingList:', error);
    }
  }

  chrome.runtime.onInstalled.addListener(
    async (details: chrome.runtime.InstalledDetails) => {
      // Cleanup old quick-record content script
      chrome.tabs.query({}, (tabs) => {
        tabs.forEach((tab) => {
          if (tab.id && tab.url?.startsWith('http')) {
            chrome.scripting
              .executeScript({
                target: { tabId: tab.id, allFrames: true },
                func: removeQuickRecordContentScript,
              })
              .catch(() => {
                /*
                  If the context prohibits the execution of scripts, we ignore the error,
                  since the script to inject the content was not previously executed either.
                */
              });
          }
        });
      });

      const removeQuickRecordContentScript = () => {
        const element = document.getElementById('quick-start-container');
        if (element) element.remove();
      };

      // Remove any invalid videos
      await removeInvalidVideos();

      // Uninstall redirect
      chrome.runtime.setUninstallURL(environment.externalLinks.uninstallUrl);

      // Always set this url so it will be valid for all users regardless of update reason except for org policy
      const { disableQuickstartGuide = false } =
        await chrome.storage.managed.get();
      if (
        details.reason === chrome.runtime.OnInstalledReason.INSTALL &&
        !disableQuickstartGuide
      ) {
        await openGettingStartedPage();
      }

      if (details.previousVersion === undefined) {
        await chrome.storage.local.set({ schema: SCHEMA });
      } else if (
        details.reason === chrome.runtime.OnInstalledReason.UPDATE &&
        details.previousVersion !== undefined
      ) {
        logger.info(
          `MV3 update detected (from ${details.previousVersion} to ${currentVersion})`,
        );
        const [prevMajor] = details.previousVersion.split('.').map(Number);

        // Migrate MV2 settings to MV3
        // MV2's last version is 3.X.x, MV3's first version is 4.X.x
        if (prevMajor <= 3) {
          const success = await migrateMv2Settings();
          if (!success) {
            logger.error('Failed to migrate MV2 settings');
          } else {
            await chrome.storage.local.set({ schema: 1 });
          }
        }

        // Migrate MV3 local storage data
        const { schema } = await chrome.storage.local.get('schema');
        const fromSchema = typeof schema === 'number' ? schema : null;
        const toSchema = SCHEMA;
        if (fromSchema === null) {
          await chrome.storage.local.set({ schema: toSchema });
          return;
        } else if (fromSchema === toSchema) {
          logger.info('Skipping migrations');
          return;
        }
        const migrations = getMigrationsInRequiredOrder(
          mv3Migrations,
          fromSchema,
          toSchema,
        );
        if (migrations.length === 0) {
          logger.warn(
            `No migrations found for schema version update ${fromSchema} to ${toSchema}. Skipping migrations`,
          );
          return;
        }
        const direction = fromSchema < toSchema ? 'up' : 'down';
        logger.info(
          `Target local storage schema version is ${toSchema}. Migration ${direction} needed. Starting migration`,
        );
        const failedMigration = await runMigrations(migrations, direction);
        if (failedMigration) {
          logger.error(
            `Failed to migrate local storage schema version ${direction} given ${JSON.stringify(
              failedMigration,
            )}`,
          );
          return;
        }
        logger.info(
          `Successfully migrated local storage ${direction} from schema version ${fromSchema} to ${toSchema}`,
        );
      }
    },
  );

  chrome.tabs.onCreated.addListener(async (tab) => {
    if (tab.pendingUrl?.includes('controller.html')) {
      await chrome.storage.local.set({ controllerTabId: tab.id });
    } else {
      maybeSaveStudioTabInfo(tab.id as number);
    }
  });

  /**
   * this will handle closing of the controller tab and studio tabs currently in the middle of an upload
   */
  chrome.tabs.onRemoved.addListener(async (tabId) => {
    const storageResult = (await chrome.storage.local.get([
      'controllerTabId',
    ])) as unknown as ControllerIdStorageResult;
    if (tabId === storageResult.controllerTabId) {
      const { recorderStatus } = (await chrome.storage.local.get([
        'recorderStatus',
      ])) as unknown as RecorderStatusStorageResult;
      //if we close during one of these states force status to error so we teardown injection properly
      //Teardown in Extension.tsx removes the recorderStatus key so this is the extent of clean up we need to do
      if (isSensitiveRecordingState(recorderStatus)) {
        await chrome.storage.local.set({ recorderStatus: 'error' });
        await chrome.storage.local.remove('recordingInProgress');
        setExtensionIcon('error');

        logger.warn(`Controller Tab forcefully closed during recording`, {
          recorderStatus,
        });
      }
    } else {
      const tabRecordsFromStorage = await getStudioTabs();
      if (tabRecordsFromStorage.studioTabs) {
        const { tabs } = tabRecordsFromStorage.studioTabs;

        const tabFound = tabs.find((entry) => {
          return entry.tabId === tabId;
        });

        if (tabFound) {
          const data = await getObservabilityMessagesByHandoffId(
            tabFound.handoffId,
          );
          //did we find observability data for the given handoff id
          if (data && data[tabFound.handoffId]) {
            try {
              const summary = await generateIngestionRollup(
                tabFound.handoffId,
                data,
              );
              logger.info('Ingestion summary early closure', summary);
            } catch (error) {
              logger.error('Error occurred while rolling up data', error);
            }

            //clean up will remove the observability data and tab tracking data
            cleanUpObservabilityData(tabFound.handoffId);
          }
        }
      }
    }
  });

  // CFY 780: these are the only tab updates that mean we're refreshing,
  // the typescript stuff here is annoying but gives us autocomplete
  // the source of this bug was that the 'isAudible' update would fire,
  // and the original implementation of this listener would think
  // the page was refreshed. See below for what shows up in changeinfo
  // https://developer.chrome.com/docs/extensions/reference/tabs/#event-onUpdated
  const TAB_REFRESH_EVENTS: (keyof chrome.tabs.TabChangeInfo)[] = [
    'url',
    'status',
  ];

  /**
   * this will handle reloading of the controller tab
   */
  chrome.tabs.onUpdated.addListener(async (tabId, changeInfo) => {
    const storageResult = (await chrome.storage.local.get([
      'controllerTabId',
    ])) as unknown as ControllerIdStorageResult;
    if (tabId === storageResult.controllerTabId) {
      const { recorderStatus } = (await chrome.storage.local.get([
        'recorderStatus',
      ])) as unknown as RecorderStatusStorageResult;

      // lots of things can happen on a tab that count as an update,
      // but we only care about a few. If we listen to any update we
      // will get false positives and break recording (CFY-780)
      const isTabActuallyRefreshing = TAB_REFRESH_EVENTS.some(
        (refreshIndicator) => refreshIndicator in changeInfo,
      );

      if (
        isSensitiveRecordingState(recorderStatus) &&
        isTabActuallyRefreshing
      ) {
        await chrome.storage.local.set({ recorderStatus: 'error' });
        await chrome.storage.local.remove('recordingInProgress');
        setExtensionIcon('error');
        logger.warn(`Controller Tab forcefully reloaded during recording`, {
          recorderStatus,
        });
      }
    }
  });

  const protocolHandler =
    createServiceWorkerProtocolHandler<AppExtensionProtocolDefinition>(
      {
        CFY_APPSIGNIN: async (message) => {
          if (message.payload.token) {
            const { token } = message.payload;
            await chrome.storage.local.set({ token });
          }
        },
        CFY_APPSIGNOUT: async () => {
          await signOutOfExtension();
        },
        UPLOAD_START: async (message) => {
          const { handoffId } = message.payload;
          await createObservabilityStorage(handoffId, message);
        },
        UPLOAD_PROGRESS_UPDATE: async (message) => {
          const { handoffId } = message.payload;
          await addObservabilityMessage(handoffId, message);
        },
        REQUEST_IMPORT_START: async (message) => {
          const { handoffId } = message.payload;
          await addObservabilityMessage(handoffId, message);
        },
        PROCESSING_START: async (message) => {
          const { handoffId } = message.payload;
          await addObservabilityMessage(handoffId, message);
        },
        COMPLETED_INGESTION: async (message) => {
          const { handoffId } = message.payload;
          await addObservabilityMessage(handoffId, message);
          const data = await getObservabilityMessagesByHandoffId(handoffId);
          try {
            const summary = await generateIngestionRollup(handoffId, data);
            logger.info('Ingestion summary', summary);
          } catch (error) {
            logger.error('Error occurred while rolling up data', error);
          }

          cleanUpObservabilityData(handoffId);
        },
        INGESTION_ERROR: async (message) => {
          logger.info('Received ingestion error message', message);
          const { handoffId } = message.payload;
          await addObservabilityMessage(handoffId, message);
          const data = await getObservabilityMessagesByHandoffId(handoffId);
          try {
            const summary = await generateIngestionRollup(handoffId, data);
            logger.info('Ingestion summary with error', summary);
          } catch (error) {
            logger.error('Error occurred while rolling up data', error);
          }
        },
      },
      logger,
    );

  chrome.runtime.onMessageExternal.addListener(protocolHandler);

  /**
   * External messages should arrive in the form { type, data }
   */
  chrome.runtime.onMessageExternal.addListener(
    async (message, sender, sendResponse) => {
      if (sender.origin !== environment.webAppUrl) {
        logger.warn(
          `received message from unexpected origin: ${sender.origin}`,
        );
        return;
      }
      // The extension id for mv2 and mv3 is the same, this function can receive messages for mv2 if are triggered
      if (message.type === 'bg:isInstalled') {
        return sendResponse(false);
      }
      // Handle the message the check if the mv3 extension is installed
      else if (message.type === 'mv3:isInstalled') {
        return sendResponse({
          success: true,
          version: chrome.runtime.getManifest().version,
        });
      }
      // Handle the message to open the popup
      else if (message.type === 'mv3:openExtension') {
        if (typeof chrome.action.openPopup === 'function') {
          chrome.action.openPopup();
          sendResponse({ success: true });
        } else {
          return sendResponse({ success: false });
        }
      }
      // Handle the message to open the controller tab
      else if (message.type === 'mv3:openController') {
        navigateToControllerTab();
        sendResponse({ success: true });
      } else {
        return sendResponse({ success: false });
      }

      sendResponse(true);
    },
  );

  async function getIsControllerTabAlive() {
    const controllerTabArray = await chrome.tabs.query({
      url: `${globalThis.location.origin}/controller.html`,
    });

    return controllerTabArray.length !== 0;
  }

  async function createControllerTab() {
    const isControllerTabAlive = await getIsControllerTabAlive();
    if (isControllerTabAlive) return;

    chrome.tabs.create({
      url: 'controller.html',
      active: false,
      pinned: true,
    });
  }

  async function navigateToControllerTab() {
    const [controllerTab] = await chrome.tabs.query({
      url: `${globalThis.location.origin}/controller.html`,
    });

    if (controllerTab?.id !== undefined) {
      if (controllerTab.windowId !== undefined) {
        await chrome.windows.update(controllerTab.windowId, { focused: true });
      }
      await chrome.tabs.update(controllerTab.id, { active: true });
      return;
    }

    await chrome.tabs.create({
      url: 'controller.html',
      active: true,
      pinned: true,
    });
  }

  const toggleStartStop = async () => {
    chrome.runtime.sendMessage({
      command: 'TOGGLE_START_STOP',
      target: 'controller',
    });
  };
  const throttledToggleStartStop = throttle(toggleStartStop, 3000);

  const toggleResumePause = async () => {
    chrome.runtime.sendMessage({
      command: 'TOGGLE_RESUME_PAUSE',
      target: 'controller',
    });
  };
  const throttledToggleResumePause = throttle(toggleResumePause, 300);

  const toggleStartStopListener = ({ command }: { command: string }) => {
    if (command === 'CONTROLLER_READY') {
      throttledToggleStartStop();
      chrome.runtime.onMessage.removeListener(toggleStartStopListener);
    }
  };

  chrome.commands.onCommand.addListener(async (command) => {
    const { isAuth } = useAuthStore.getState();
    if (!isAuth) {
      chrome.action.openPopup();
      return;
    }
    const isControllerTabAlive = await getIsControllerTabAlive();
    if (command === 'toggle-start-stop') {
      if (!isControllerTabAlive) {
        createControllerTab();
        chrome.runtime.onMessage.addListener(toggleStartStopListener);
      } else throttledToggleStartStop();
    } else if (command === 'toggle-resume-pause') {
      if (!isControllerTabAlive) return;
      throttledToggleResumePause();
    }
  });

  chrome.runtime.onMessage.addListener(async ({ command }, _, sendResponse) => {
    const { isAuth } = useAuthStore.getState();
    if (!isAuth) {
      chrome.action.openPopup();
      return;
    }
    if (command !== 'toggle-start-stop') return;
    const isControllerTabAlive = await getIsControllerTabAlive();
    if (!isControllerTabAlive) {
      createControllerTab();
      chrome.runtime.onMessage.addListener(toggleStartStopListener);
    } else throttledToggleStartStop();
    sendResponse(true);
    return true;
  });

  chrome.runtime.onMessage.addListener(async ({ command }, _, sendResponse) => {
    if (command !== 'open-popup') return;
    chrome.action.openPopup();
    sendResponse(true);
    return true;
  });

  // Sync quick record toolbar
  const RECORDING_STATES = [
    'acquiring-media',
    'counting-in',
    'recording',
    'paused',
  ];

  // Send isRecording value to quick record content script
  chrome.storage.onChanged.addListener((changes, areaName) => {
    if (areaName !== 'local') return;
    if (!changes.recorderStatus) return;

    const wasRecording = RECORDING_STATES.includes(
      String(changes.recorderStatus.oldValue),
    );
    const isRecording = RECORDING_STATES.includes(
      String(changes.recorderStatus.newValue),
    );
    if (wasRecording === isRecording) return;

    chrome.tabs.query({}, (tabs) => {
      for (const tab of tabs) {
        if (!tab.id) continue;
        chrome.tabs.sendMessage(
          tab.id,
          {
            command: 'RECORDING_STATUS_CHANGED',
            isRecording,
          },
          () => {
            if (chrome.runtime.lastError) {
              // Ignore error
            }
          },
        );
      }
    });
  });

  // Focus to controller tab
  chrome.runtime.onMessage.addListener(async ({ command }, _, sendResponse) => {
    if (command !== 'navigate-to-controller') return;
    await createControllerTab();
    await focusControllerTab();
    sendResponse(true);
    return true;
  });
}

initBackgroundContentScript();

// Auth script
authScript();

// Counter script
counterScript();
