export enum View {
  Grid = 'grid',
  List = 'list',
}

export enum StorageType {
  DRIVE = 'drive',
  CLOUD = 'cloud',
}

export enum UserPersonalSettingKeys {
  VideosPreferredView = 'myVideosPreferredView',
  PersistentStorage = 'persistentStorage',
}

export const USER_SETTINGS_QUERY_KEY = 'user-settings';

export interface ViewSetting {
  name: UserPersonalSettingKeys.VideosPreferredView;
  value: View;
}

export interface StorageSetting {
  name: UserPersonalSettingKeys.PersistentStorage;
  value: StorageType;
}

export interface PersonalSettings {
  count: number;
  items: [ViewSetting?, StorageSetting?];
}
