/* The below functions are here, in a separate
 * library that does not include UI components, as UI components cannot be loaded
 * in service workers without tree shaking (which doesn't occur in dev mode)
 */
export const findCloseControllerTab = async () => {
  const controllerTabArray = await chrome.tabs.query({
    url: `${globalThis.location.origin}/controller.html`,
  });

  if (controllerTabArray.length > 0) {
    const closingPromises = controllerTabArray.map((tab) => {
      if (tab.id) chrome.tabs.remove(tab.id);
    });
    await Promise.all(closingPromises);
  }
};
