/* eslint-disable @typescript-eslint/no-unused-vars */
import { StorageType } from '@castify/record-mv3/common';
import { Migration } from '../util/schema';
export const RECORDING_SETTINGS_LOCAL_STORAGE_KEY = 'recordingSettings';
export const RECORDING_STORE_LOCAL_STORAGE_KEY = 'recordingStore';

/**
 * @summary
 * A running list of migrations to transform local storage data from one schema to the next.
 *
 * @description
 * To test you will need to run the following commands in the service worker's dev tools:
 *
 * ```ts
 * // 1. Get the current schema and MV3 recording settings
 * chrome.storage.local.get(['schema', 'recordingSettings'], (result) => { console.log(JSON.stringify(result)) })
 * // 2. Set the current schema for MV3
 * chrome.storage.local.set({ 'schema': 1 })
 * ```
 *
 * The testing strategy is as follows:
 *
 * 1. Be serving the staging extension locally
 * 2. Have the extension loaded as an unpacked extension
 * 3. Click the refresh button to update the extension
 * 4. Click the link to inspect the service worker
 * 5. Run command 1 (above) and keep the output for reference
 * 6. Go to `types/schema.ts` and change `SCHEMA` to a value between 1 and the highest schema
 * 7. Save the change and repeat steps 3 - 5
 *
 * If the schema you typed in step 6 was different than the one you saw in step 5, you should be migrated.
 *
 * You can identify a successful migration by noting the differences between the schemas and settings data.
 *
 * If the migration was unsuccessful, the schema will not have updated and the data should be the same.
 *
 * If you need to reset your data, go to the Options page and add `?debug=true` to the URL.
 *
 * After resetting you can manually set your schema with the command 2, referenced above.
 */

interface ExtendedMetadata extends Metadata {
  source?: StorageType;
}
interface Recording {
  id: string;
  autoUpload: boolean;
  userId: string;
  metadata: ExtendedMetadata;
}

export const mv3Migrations: Migration[] = [
  {
    from: 1,
    to: 2,
    up: async () => {
      // Change recordingSettings adding userCastLengthLimit
    },
    down: async () => {
      // Change recordingSettings removing userCastLengthLimit
      const data = await chrome.storage.local.get(
        RECORDING_SETTINGS_LOCAL_STORAGE_KEY,
      );
      const recordingSettings = data[RECORDING_SETTINGS_LOCAL_STORAGE_KEY];
      delete recordingSettings.userCastLengthLimit;
      await chrome.storage.local.set({
        [RECORDING_SETTINGS_LOCAL_STORAGE_KEY]: recordingSettings,
      });
    },
  },
  {
    from: 2,
    to: 3,
    up: async () => {
      // Change recordingSettings adding videoStorageLocation
      const data = await chrome.storage.local.get(
        RECORDING_SETTINGS_LOCAL_STORAGE_KEY,
      );
      const recordingSettings = data[RECORDING_SETTINGS_LOCAL_STORAGE_KEY];
      await chrome.storage.local.set({
        [RECORDING_SETTINGS_LOCAL_STORAGE_KEY]: {
          ...recordingSettings,
          videoStorageLocation: 'google-drive',
        },
      });

      // Add autoUpload value to each recording in recordingStore
      const recordingStoreData = await chrome.storage.local.get(
        RECORDING_STORE_LOCAL_STORAGE_KEY,
      );
      const recordingStore =
        recordingStoreData[RECORDING_STORE_LOCAL_STORAGE_KEY];
      const newRecordingList = recordingStore.recordingList.map(
        (recording: Recording) => {
          return {
            ...recording,
            autoUpload: true,
          };
        },
      );
      await chrome.storage.local.set({
        [RECORDING_STORE_LOCAL_STORAGE_KEY]: {
          ...recordingStore,
          recordingList: newRecordingList,
        },
      });
    },
    down: async () => {
      // Change recordingSettings removing videoStorageLocation
      const data = await chrome.storage.local.get(
        RECORDING_SETTINGS_LOCAL_STORAGE_KEY,
      );
      const recordingSettings = data[RECORDING_SETTINGS_LOCAL_STORAGE_KEY];
      delete recordingSettings.videoStorageLocation;
      await chrome.storage.local.set({
        [RECORDING_SETTINGS_LOCAL_STORAGE_KEY]: recordingSettings,
      });

      // Remove autoUpload value to each recording in recordingStore
      const recordingStoreData = await chrome.storage.local.get(
        RECORDING_STORE_LOCAL_STORAGE_KEY,
      );
      const recordingStore =
        recordingStoreData[RECORDING_STORE_LOCAL_STORAGE_KEY];
      const newRecordingList = recordingStore.recordingList.map(
        ({ autoUpload, ...recording }: Recording) => {
          return recording;
        },
      );
      await chrome.storage.local.set({
        [RECORDING_STORE_LOCAL_STORAGE_KEY]: {
          ...recordingStore,
          recordingList: newRecordingList,
        },
      });
    },
  },
  {
    from: 3,
    to: 4,
    up: async () => {
      // Change recordingSettings adding metadata.source
      const data = await chrome.storage.local.get(
        RECORDING_SETTINGS_LOCAL_STORAGE_KEY,
      );
      const recordingSettings = data[RECORDING_SETTINGS_LOCAL_STORAGE_KEY];
      await chrome.storage.local.set({
        [RECORDING_SETTINGS_LOCAL_STORAGE_KEY]: {
          ...recordingSettings,
          metadata: {
            ...recordingSettings.metadata,
            source: 'drive',
          },
        },
      });
      // Add source value to each recording in recordingStore
      const recordingStoreData = await chrome.storage.local.get(
        RECORDING_STORE_LOCAL_STORAGE_KEY,
      );
      const recordingStore =
        recordingStoreData[RECORDING_STORE_LOCAL_STORAGE_KEY];
      const newRecordingList = recordingStore.recordingList.map(
        (recording: Recording) => {
          return {
            ...recording,
            metadata: {
              ...recordingSettings.metadata,
              source: 'drive',
            },
          };
        },
      );
      await chrome.storage.local.set({
        [RECORDING_STORE_LOCAL_STORAGE_KEY]: {
          ...recordingStore,
          recordingList: newRecordingList,
        },
      });
    },
    down: async () => {
      // Change recordingSettings removing videoStorageLocation
      const data = await chrome.storage.local.get(
        RECORDING_SETTINGS_LOCAL_STORAGE_KEY,
      );
      const recordingSettings = data[RECORDING_SETTINGS_LOCAL_STORAGE_KEY];
      if (recordingSettings.metadata?.source)
        delete recordingSettings.metadata.source;
      await chrome.storage.local.set({
        [RECORDING_SETTINGS_LOCAL_STORAGE_KEY]: recordingSettings,
      });
      // Remove autoUpload value to each recording in recordingStore
      const recordingStoreData = await chrome.storage.local.get(
        RECORDING_STORE_LOCAL_STORAGE_KEY,
      );
      const recordingStore =
        recordingStoreData[RECORDING_STORE_LOCAL_STORAGE_KEY];
      const newRecordingList = recordingStore.recordingList.map(
        (recording: Recording) => {
          if (recording.metadata?.source) delete recording.metadata.source;

          return recording;
        },
      );
      await chrome.storage.local.set({
        [RECORDING_STORE_LOCAL_STORAGE_KEY]: {
          ...recordingStore,
          recordingList: newRecordingList,
        },
      });
    },
  },
  {
    from: 4,
    to: 5,
    up: async () => {
      // Add userId value to each recording in recordingStore
      const recordingStoreData = await chrome.storage.local.get(
        RECORDING_STORE_LOCAL_STORAGE_KEY,
      );
      const recordingStore =
        recordingStoreData[RECORDING_STORE_LOCAL_STORAGE_KEY];
      const newRecordingList = recordingStore.recordingList.map(
        (recording: Recording) => {
          return {
            ...recording,
            userId: '',
          };
        },
      );
      await chrome.storage.local.set({
        [RECORDING_STORE_LOCAL_STORAGE_KEY]: {
          ...recordingStore,
          recordingList: newRecordingList,
        },
      });
    },
    down: async () => {
      // Remove userId value from each recording in recordingStore
      const recordingStoreData = await chrome.storage.local.get(
        RECORDING_STORE_LOCAL_STORAGE_KEY,
      );
      const recordingStore =
        recordingStoreData[RECORDING_STORE_LOCAL_STORAGE_KEY];
      const newRecordingList = recordingStore.recordingList.map(
        ({ userId, ...recording }: Recording) => {
          return recording; // Remove userId
        },
      );
      await chrome.storage.local.set({
        [RECORDING_STORE_LOCAL_STORAGE_KEY]: {
          ...recordingStore,
          recordingList: newRecordingList,
        },
      });
    },
  },
];
