import { environment } from '@castify/record-mv3/environment';
import { getFirebaseAccessToken } from '@castify/record-mv3/observability';
import { ServiceWorkerLogger } from '@cfy/fe-monitoring';

const logger = new ServiceWorkerLogger(
  environment.logServiceUrl,
  getFirebaseAccessToken,
  {
    appName: 'record-mv3-migrate-mv2-settings',
    buildId: chrome.runtime.getManifest().version_name,
  },
);

const RECORDING_SETTINGS_LOCAL_STORAGE_KEY = 'recordingSettings';

export const MV2_RECORD_CONFIG_LOCAL_STORAGE_KEY = 'recordConfig' as const;
export const MV2_OPTIONS_LOCAL_STORAGE_KEY = 'options' as const;

export interface MV2LocalStorageResponse {
  [MV2_RECORD_CONFIG_LOCAL_STORAGE_KEY]:
    | MV2RecordConfig
    | LocalStorageNoResultResponse;
  [MV2_OPTIONS_LOCAL_STORAGE_KEY]: MV2AppOptions | LocalStorageNoResultResponse;
}

export type LocalStorageNoResultResponse = Record<never, never>;

export interface MV2RecordConfig {
  audio: { mic: boolean; system: boolean };
  camSourceId: string;
  captureSource: string;
  draw: { showToolbox: boolean; tool: string };
  embedWebcam: boolean;
  exportFormat: string;
  limitResolution: boolean;
  maxResolution: { height: number; width: number };
  showPreview: boolean;
  startDelay: number;
  targetFPS: number;
  visualCountdown: boolean;
}

export interface MV2AppOptions {
  micAudioProcessing: boolean;
  micGain: number;
}

// For now just detects if there are any keys. Be more specific if needed.
function isMv2Options(data: unknown): data is MV2AppOptions {
  return (
    data !== null && typeof data === 'object' && Object.keys(data).length > 0
  );
}

// For now just detects if there are any keys. Be more specific if needed.
function isMv2RecordConfig(data: unknown): data is MV2RecordConfig {
  return (
    data !== null && typeof data === 'object' && Object.keys(data).length > 0
  );
}

export function convertMv2ResolutionToMv3Preset(
  limitResolution: boolean,
  {
    height,
  }: {
    height: number;
    width: number;
  },
) {
  if (!limitResolution) return 'OFF';
  else if (height >= 2160) return '4k';
  else if (height >= 1080) return '1080p';
  else if (height >= 720) return '720p';
  else if (height >= 480) return '480p';
  else return '360p';
}

export function convertMv2FrameRateToMv3Preset(frameRate: number) {
  switch (frameRate) {
    case 1:
      return '1fps';
    case 5:
      return '5fps';
    case 10:
      return '10fps';
    case 30:
      return '30fps';
    case 60:
      return '60fps';
    default:
      return '30fps';
  }
}

export async function migrateMv2Settings(
  // eslint-disable-next-line @typescript-eslint/no-unused-vars
  targetSchema?: number, // TODO: Use this to figure out which keys to set in MV3 local storage
): Promise<boolean> {
  const response = await chrome.storage.local.get([
    MV2_RECORD_CONFIG_LOCAL_STORAGE_KEY,
    MV2_OPTIONS_LOCAL_STORAGE_KEY,
  ]);

  const recordConfig = response[MV2_RECORD_CONFIG_LOCAL_STORAGE_KEY];
  const options = response[MV2_OPTIONS_LOCAL_STORAGE_KEY];
  if (!isMv2RecordConfig(recordConfig) || !isMv2Options(options)) {
    logger.error(
      `Received unexpected data from local storage.\n${MV2_OPTIONS_LOCAL_STORAGE_KEY}: ${JSON.stringify(
        recordConfig,
      )}\n${MV2_OPTIONS_LOCAL_STORAGE_KEY}: ${JSON.stringify(options)}`,
    );
    return false;
  }

  const recordingSettings = {
    showDrawingTools: recordConfig.draw.showToolbox,
    selectedResolution: convertMv2ResolutionToMv3Preset(
      recordConfig.limitResolution,
      recordConfig.maxResolution,
    ),
    useCountIn: recordConfig.visualCountdown,
    countInDuration: recordConfig.startDelay,
    selectedFrameRate: convertMv2FrameRateToMv3Preset(recordConfig.targetFPS),
    useNoiseSuppression: options.micAudioProcessing,
  };

  logger.info(
    `Setting local storage key ${RECORDING_SETTINGS_LOCAL_STORAGE_KEY} to ${JSON.stringify(
      recordingSettings,
    )}`,
  );
  await chrome.storage.local.set({
    [RECORDING_SETTINGS_LOCAL_STORAGE_KEY]: recordingSettings,
  });

  return true;
}
