import {
  useEffect,
  useState,
  useContext,
  createContext,
  ReactNode,
} from 'react';

export type VideoCommentPrivacy = 'public' | 'private' | 'disabled';

export const DEFAULT_OPTIONS: VMPAppOptions = {
  hasSilencedTrimConfirm: false,
  hasSilencedEditorConfirm: false,
  hasSilencedEmbedCopyConfirm: false,
  customDefaultVideoPermission: null,
  customDefaultDomainPermissionList: null,
  commentsPrivacy: 'public',
  isCommentsNotificationEnabled: true, // CFY-3169 Default to true
};

export type VMPAppOptions = {
  // Whether or not the user has silenced the trim confirmation dialog
  hasSilencedTrimConfirm: boolean;
  // Show a secondary confirmation dialog before opening the editor from the VDP button
  hasSilencedEditorConfirm: boolean;
  // Whether or not the user has silenced the embed code privacy confirmation dialog
  hasSilencedEmbedCopyConfirm: boolean;
  customDefaultVideoPermission: string | null;
  // saved default domains for a video with default 'domain' privacy setting
  customDefaultDomainPermissionList: Array<string> | null;
  /** Default value for video comment privacy setting. */
  commentsPrivacy: VideoCommentPrivacy;
  // Default value for whether or not to send comment notifications
  isCommentsNotificationEnabled?: boolean;
};

export type FisVmpOptions = VMPAppOptions & {
  commentsPrivacy?: VideoCommentPrivacy;
  isCommentsNotificationEnabled?: boolean;
};

export type VMPAppOptionKey = keyof VMPAppOptions;

interface AppOptionsState {
  appOptions: VMPAppOptions;
}
const AppOptionsContext = createContext<AppOptionsState | undefined>(undefined);

export const useAppOptions = () => {
  const contextValue = useContext(AppOptionsContext);

  if (contextValue === undefined) {
    throw new Error('useAppOptions must be used within a AppOptionsProvider');
  }

  return contextValue;
};

interface Props {
  children: ReactNode;
}
export function AppOptionsProvider({ children }: Props) {
  const [appOptions, setAppOptions] = useState<VMPAppOptions>(DEFAULT_OPTIONS);

  useEffect(() => {
    const getAppOptions = async () => {
      const newAppOptions = await chrome.runtime
        .sendMessage({
          command: 'firestore-options',
        })
        .catch(() => {}); // Ignore error if extension context has changed
      setAppOptions(newAppOptions ?? DEFAULT_OPTIONS);
    };
    getAppOptions();
  }, []);

  return (
    <AppOptionsContext.Provider value={{ appOptions }}>
      {children}
    </AppOptionsContext.Provider>
  );
}
