import { environment } from '@castify/record-mv3/environment';
import { Migration } from '../util/schema';
import { getFirebaseAccessToken } from '@castify/record-mv3/observability';
import { ServiceWorkerLogger } from '@cfy/fe-monitoring';

const logger = new ServiceWorkerLogger(
  environment.logServiceUrl,
  getFirebaseAccessToken,
  {
    appName: 'record-mv3-migration-tools',
    buildId: chrome.runtime.getManifest().version_name,
  },
);

/**
 * Runs a list of schema migrations.
 * @async
 * @function runMigrations
 * @param {Migration[]} migrations a pre-sorted and filtered list of migrations to run.
 * @param {string} direction the direction to run the migrations in.
 * @retuns the failed migration when a migration fails to run, otherwise void.
 */
export async function runMigrations(
  migrations: Migration[],
  direction: 'up' | 'down',
): Promise<void | Migration> {
  logger.info(`Running ${migrations.length} schema migrations ${direction}`);
  for (const migration of migrations) {
    const fromSchema = direction === 'up' ? migration.from : migration.to;
    const toSchema = direction === 'up' ? migration.to : migration.from;
    try {
      await migration[direction]();
    } catch (error) {
      logger.error(
        `Failed to migrate schema version from ${fromSchema} to ${toSchema}.` +
          error,
      );
      return migration;
    }
    logger.info(
      `Successfully migrated from schema version ${fromSchema} to ${toSchema}. Setting schema version to ${toSchema}`,
    );
    await chrome.storage.local.set({ schema: toSchema });
  }
}

/**
 * Filters down a sorted list of schema migrations.
 * @function getMigrationsInRequiredOrder
 * @param {Migration[]} migrations a list of migrations to sort and filter.
 * @param {number} from the current schema version the user is on.
 * @param {number} to the target schema version we want the user to be on.
 * @returns {Migration[]} the list of migrations in the order they should be applied, given the direction of migration.
 */
export function getMigrationsInRequiredOrder(
  migrations: Migration[],
  from: number,
  to: number,
): Migration[] {
  if (from === to || from < 1 || to < 1) return [];
  const direction = from < to ? 'up' : 'down';
  const requiredMigrations = migrations.filter((m) =>
    direction === 'up'
      ? m.from < to && m.to > from
      : m.from >= to && m.to <= from,
  );
  const sortedMigrations = requiredMigrations.sort(
    ({ from: fromA }, { from: fromB }) =>
      direction === 'up' ? fromA - fromB : fromB - fromA,
  );
  return sortedMigrations;
}
