import { environment } from '@castify/record-mv3/environment';
import { initializeApp } from 'firebase/app';
import { doc, getDoc, getFirestore, setDoc } from 'firebase/firestore';
import {
  getAuth,
  GoogleAuthProvider,
  signInWithCredential,
  signInWithCustomToken,
} from 'firebase/auth/web-extension';
import { getFirebaseAccessToken } from '@castify/record-mv3/observability';
import { ServiceWorkerLogger } from '@cfy/fe-monitoring';
import {
  signOutOfExtension,
  findCloseControllerTab,
} from '@castify/record-mv3/common/auth';
import { useAuthStore } from '@castify/record-mv3/common/stores';
import { getExtensionBrowserType } from '@castify/record-mv3/environment';
import { converter } from './gmail-content-script/VideoPickerModal/PrivacyDialog/utils/converter';
import {
  FisVmpOptions,
  DEFAULT_OPTIONS,
} from './gmail-content-script/VideoPickerModal/PrivacyDialog/hooks/useAppOptions';

const REFRESH_TOKENS_INTERVAL = 45; // 45 min

const currentVersion =
  chrome.runtime.getManifest().version_name + getExtensionBrowserType();
const logger = new ServiceWorkerLogger(
  environment.logServiceUrl,
  getFirebaseAccessToken,
  {
    appName: 'record-mv3-auth-script-worker',
    buildId: currentVersion,
  },
);

// AUTH SCRIPT
export async function authScript() {
  const { loadStore } = useAuthStore.getState();
  loadStore();

  const firebaseApp = initializeApp(environment.firebaseConfig);
  const firebaseAuth = getAuth(firebaseApp);

  // Listen auth changes
  firebaseAuth.onAuthStateChanged(async (user) => {
    if (!user) {
      logger.info('User not authenticated');
      useAuthStore.getState().resetUser();
      await chrome.storage.local.remove(['userState', 'DRIVE_FOLDER_ID']);
      await findCloseControllerTab();
      return;
    }
    useAuthStore.getState().setUser({
      userId: user.uid,
      name: user.displayName,
      email: user.email,
    });
    const userId = useAuthStore.getState().userId;
    logger.info(`New user authentication: ${userId}`);
  });

  // Listen token changes
  firebaseAuth.onIdTokenChanged(async (user) => {
    if (!user) return;
    useAuthStore.getState().setIsFirebaseTokenRefreshing(true);

    const newFirebaseToken = await user.getIdToken();
    if (!newFirebaseToken) {
      logger.error('Error on refresh firebase token');
      useAuthStore.getState().setIsFirebaseTokenRefreshing(false);
      return;
    }
    useAuthStore.getState().setFirebaseAccessToken(newFirebaseToken);

    useAuthStore.getState().setIsAuthentified(true);
    useAuthStore.getState().setIsFirebaseTokenRefreshing(false);
  });

  // Alarm to wake up background script and refresh firebase token
  chrome.alarms.create('refreshFirebaseToken', {
    periodInMinutes: REFRESH_TOKENS_INTERVAL,
  });

  chrome.alarms.onAlarm.addListener(async (alarm) => {
    if (alarm.name !== 'refreshFirebaseToken') return;
    if (!firebaseAuth.currentUser) return;
    firebaseAuth.currentUser.getIdToken(true).catch((e) => {
      logger.error('Error on auto refresh token', e);
    });
  });

  // Event to get a fresh firebase token
  chrome.runtime.onMessage.addListener(
    (message: { type: string }, _sender, sendResponse) => {
      if (message.type !== 'refreshFirebaseToken') return;

      if (!firebaseAuth.currentUser) {
        sendResponse({ success: false, error: 'No user authenticated' });
        return;
      }

      firebaseAuth.currentUser
        .getIdToken(true)
        .then((newToken) => sendResponse({ success: true, token: newToken }))
        .catch((error) =>
          sendResponse({ success: false, error: error.message }),
        );

      return true;
    },
  );

  // Listeners from handover page
  chrome.runtime.onMessageExternal.addListener(
    async (message, sender, sendResponse) => {
      if (sender.origin !== environment.webAppUrl) {
        logger.warn(
          `received message from unexpected origin: ${sender.origin}`,
        );
        return;
      }
      if (message.type === 'mv3:extensionAuth:signInWithToken') {
        const isAuth = useAuthStore.getState().isAuth;
        if (isAuth) return;

        // Login
        const { customToken, isEmailPwdUser } = message.data;
        if (!customToken) {
          const { googleAccessToken, googleIdToken } = message.data;
          const credential = googleIdToken
            ? GoogleAuthProvider.credential(googleIdToken)
            : GoogleAuthProvider.credential(null, googleAccessToken);
          signInWithCredential(firebaseAuth, credential).catch((error) => {
            logger.error('Error on sign in with old auth:', error);
          });
        } else {
          signInWithCustomToken(firebaseAuth, customToken).catch((error) => {
            logger.error('Error on sign in with new auth:', error);
          });
        }
        if (isEmailPwdUser) useAuthStore.getState().setEmailPwdUser(true);
      } else if (message.type === 'mv3:extensionAuth:signout') {
        await signOutOfExtension();
      }
      sendResponse(true);
    },
  );

  chrome.runtime.onMessage.addListener(async (message, _, sendResponse) => {
    if (message.command !== 'firestore-options') return;

    const firebaseApp = initializeApp(environment.firebaseConfig);
    const firestore = getFirestore(firebaseApp);
    const userId = useAuthStore.getState().userId;

    const documentReference = doc(
      firestore,
      `appOptions/${userId}`,
    ).withConverter(converter<FisVmpOptions>());

    const snapshot = await getDoc(documentReference);
    const data = snapshot.data();
    if (!data || !data.commentsPrivacy) {
      const mergedData = { ...DEFAULT_OPTIONS, ...data };
      await setDoc(documentReference, mergedData, { merge: true });
      sendResponse(mergedData);
      return true;
    }

    sendResponse(data);
    return true;
  });
}
