import { useCountdownStore } from '@castify/record-mv3/common/stores';
import { setExtensionIconWhileCountingIn } from '@castify/record-mv3/chrome-actions';
import { delay } from './util/delay';

export const counterScript = () => {
  const startCountdown = async (duration: number) => {
    useCountdownStore.getState().setTimeLeft(duration);
    useCountdownStore.getState().setVisible(true);

    await delay(1500);

    for (let t = duration; t > 0; t--) {
      useCountdownStore.getState().setTimeLeft(t);
      setExtensionIconWhileCountingIn(t);

      chrome.runtime.sendMessage({
        command: 'AUDIO_COUNTDOWN_TICK',
      });
      await delay(1000);
    }

    useCountdownStore.getState().reset();
    chrome.runtime.sendMessage({
      command: 'AUDIO_COUNTDOWN_DONE',
    });

    await delay(200);
    chrome.runtime.sendMessage({
      command: 'RECORDING_CONTROLLER_IMMEDIATE_START',
    });
  };

  chrome.runtime.onMessage.addListener(
    async ({ command, payload }, _, sendResponse) => {
      if (command !== 'start-countdown') return;

      const duration = payload?.duration ?? 3;
      await startCountdown(duration);
      sendResponse(true);
      return true;
    },
  );
};
